import math

def check_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n, sqrt_n

solutions = []
for b in range(1, 8):
    # The quadratic equation is: a^2 - a*(2^(b+1) - 1) + 2 * 3^b = 0

    C = 2**(b+1) - 1
    const = 2 * (3**b)

    # Discriminant D = C^2 - 4 * 1 * const
    D = C**2 - 4 * const

    is_square, m = check_perfect_square(D)

    if is_square:
        # Solutions for a: a = (C +/- m) / 2

        # Check solution 1: a1 = (C + m) / 2
        if (C + m) % 2 == 0:
            a1 = (C + m) // 2
            if a1 > 0:
                solutions.append((a1, b))

        # Check solution 2: a2 = (C - m) / 2
        if (C - m) % 2 == 0:
            a2 = (C - m) // 2
            if a2 > 0:
                solutions.append((a2, b))

print("Solutions (a, b) for b=1 to b=7:")
for sol in solutions:
    print(sol)

# Calculate the sum requested: sum(a_i + b_i)
total_sum = 0
for a, b in solutions:
    total_sum += (a + b)

print(f"\nTotal sum of (a_i + b_i): {total_sum}")

